/// without first running `callisto version`, which would otherwise silently
/// publish the old on-disk version.
pub fn cargo_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    registry_key: Option<&str>,
) -> Result<Argv, GraphError> {
    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;

    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let mut args = vec![
        "publish".to_string(),
        "--manifest-path".to_string(),
        manifest_path.to_string_lossy().into_owned(),
        "--locked".to_string(),
    ];
    if let Some(reg) = registry_key {
        args.push("--registry".to_string());
        args.push(reg.to_string());
    }
    Ok(Argv {
        program: "cargo".to_string(),
        args,
        cwd: workspace_root.to_path_buf(),
    })
}

fn verify_cargo_ondisk_version(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    planned: &Version,
) -> Result<(), GraphError> {
    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    // Parse only the [package].version field -- no need for full CST. A
    // permissive `toml::Value` intermediate rather than a direct `String`
    // deserialization, because `version.workspace = true` (Cargo's
    // workspace-version-inheritance syntax) parses `version` as a table, not
    // a string.
    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    let version_value =
        parsed
            .get("package")
            .and_then(|p| p.get("version"))
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "missing [package].version".to_string(),
        .unwrap();
        std::fs::write(root.join("crates/app/src/lib.rs"), "").unwrap();

        std::fs::write(
            root.join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/core\", \"crates/app\"]\nresolver = \"2\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, _report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let permit = callisto_model::ApplyPermit::force_for_tests();
        let opts = crate::apply::ApplyOptions::default();
        crate::apply::apply_version_plan(root, &plan, &runner, &opts, &permit).expect("apply must succeed");

        let target_dir = tmp.path().join("target");
        let output = std::process::Command::new("cargo")
            .args(["metadata", "--no-deps", "--format-version", "1"])
            .env("CARGO_TARGET_DIR", &target_dir)
            .current_dir(root)
            .output()
            .expect("cargo must be installed");

        assert!(
            output.status.success(),
            "cargo metadata must succeed after snapshot rewrites `core`'s spec; stderr: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    /// Plan_snapshot must never call
    /// pre_mutation_checks -- snapshot mode assigns every package the
    /// identical synthetic version, so there is no distinct-target
    /// divergence for pre_mutation_checks to ever catch here.
    #[test]
    fn plan_snapshot_source_never_calls_pre_mutation_checks() {
        let source = include_str!("snapshot.rs");
        // Only the production code above the `#[cfg(test)]` boundary is
        // checked -- this test module's own name and doc comments
        // necessarily mention `pre_mutation_checks` and must not cause a
        // self-match false failure.
        let production_source = source
            .split_once("#[cfg(test)]")
            .map(|(before, _)| before)
            .unwrap_or(source);
        assert!(
            !production_source.contains("pre_mutation_checks"),
/// Builds a PlatformTarget for `triple`, combining `triple_to_role`'s
/// platform/arch/abi with this module's hostRunner/useCross/artifactName
/// table. Returns `None` when `triple` is not recognised by either --
/// callers must route that case to an UnrecognisedPlatformTriple diagnostic
/// rather than treating it as an error.
pub(crate) fn build_platform_target(triple: &str, package_dir: &str, package_name: &str) -> Option<PlatformTarget> {
    let ManifestRole::Platform { platform, arch, abi } = triple_to_role(triple)? else {
        return None;
    };
    let (host_runner, use_cross) = triple_host_runner_use_cross(triple)?;
    let artifact_name = artifact_name_for_package_platform(package_name, &platform, &arch, abi.as_deref());
    Some(PlatformTarget {
        triple: triple.to_string(),
        platform,
        arch,
        abi,
        host_runner: host_runner.to_string(),
        use_cross,
        artifact_name,
        package_dir: package_dir.to_string(),
        package_name: package_name.to_string(),
        manifest_path: None,
    })
}

