Create a read-only durable release intent from exact package selections

Usage: callisto release plan [OPTIONS] --out <FILE>

Options:
      --format <FORMAT>
          Output format for command results [default: text] [possible values: text, json]
      --source-root <DIR>
          Read the release source from this checkout while the Callisto binary itself may come from a separate, current orchestration checkout
      --cwd <CWD>
          Workspace directory to operate in (defaults to the current directory) [default: .]
      --orchestration-revision <SHA>
          Exact current coordinator revision whose workflow will attest product assets
      --artifact-repository <OWNER/REPOSITORY>
          GitHub repository receiving the product release assets, for example `orin-dx/callisto`. Required when the workspace declares product assets
      --dry-run
          Preview manifest and file changes without writing to disk
      --package <ECOSYSTEM/NAME>
          Exact qualified package identity, for example `cargo/callisto-cli`. Repeat this flag to select multiple packages. This local/manual mode cannot be combined with --from-release-commit
      --from-release-commit <SHA>
          Exact merged release-PR commit checked out in this workspace. CI derives the roster from its versioned manifest delta and never reruns changeset planning
      --decision <FILE>
          Exact release-decision JSON path committed alongside the manifest and changelog edits in the merge commit (written by `callisto version --emit-decision`). Required with --from-release-commit: this function verifies the committed diff matches this file exactly rather than re-deriving changeset, fixed-group, linked-group, cascade, or pre-release-policy inclusion from scratch
      --out <FILE>
          Explicit path where the immutable intent JSON will be atomically written
  -h, --help
          Print help
            "--no-deps",
            "--manifest-path",
        ])
        .arg(root.join("native/Cargo.toml"))
        .output()
        .unwrap();
    assert!(
        metadata.status.success(),
        "{}",
        String::from_utf8_lossy(&metadata.stderr)
    );
}

/// The release commit is verified against the inherited version at both of its sides.
#[test]
fn a_release_commit_in_a_nested_workspace_verifies_the_version_it_inherited() {
    let dir = nested_workspace_repo();
    let root = dir.path();
    let init = callisto(root, &["init", "--yes", "--versioning", "independent"]);
    assert!(init.status.success(), "{}", String::from_utf8_lossy(&init.stderr));
    commit(root, "configure callisto");

    ok(root, &["add", "--package", "a:minor", "--summary", "A new feature"]);
    commit(root, "changeset");
    ok(root, &["version", "--emit-decision", DECISION_PATH]);
    for entry in fs::read_dir(root.join(".changeset")).unwrap() {
        let path = entry.unwrap().path();
        if path.file_name().is_some_and(|name| name != "README.md") && path.extension().is_some_and(|ext| ext == "md") {
            fs::remove_file(path).unwrap();
        }
    }
    commit(root, "release a 0.4.0");
    let release_commit = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &release_commit]);

    let external = tempfile::tempdir().unwrap();
    let intent = external.path().join("release-intent.json");
    let plan = callisto(
        root,
        &[
            "release",
            "plan",
            "--from-release-commit",
            &release_commit,
            "--decision",
            DECISION_PATH,
            "--out",
            intent.to_str().unwrap(),
        ],
    );
    assert!(plan.status.success(), "{}", String::from_utf8_lossy(&plan.stderr));
    let intent: serde_json::Value = serde_json::from_slice(&fs::read(&intent).unwrap()).unwrap();
    let entries = intent["decision"]["entries"].as_array().unwrap();
    assert!(
        entries
            .iter()
            .any(|entry| entry["package"] == "cargo/a" && entry["targetVersion"] == "0.4.0"),
        "{entries:?}"
    );
}

